156	//
157	// Implement, and have Dafny verify, the method Reverse below, which returns a new array
158	// aRev consisting of the elements of a, but in reverse order.  To create a new 
159	// array of ints use the Dafny command "new int[...]", where "..." is the number
160	// of elements in the array.
161	
162	method Reverse (a : array<int>) returns (aRev : array<int>)
163	    ensures aRev.Length == a.Length
164	    ensures forall i : int :: 0 <= i < a.Length ==> a[i] == aRev[aRev.Length-i-1] && i != 0
165	    ensures fresh(aRev) // Indicates returned object is newly created in method body
166	{
167	    aRev := new int[a.Length];
168	    var i : int := 0;
169	    while (i < a.Length)
170	        invariant 0 <= i <= a.Length
171	        invariant forall j : int :: 0 <= j < i ==> aRev[j] == a[a.Length-j-1]
172	    {
173	        aRev[i] := a[a.Length-i-1];
174	        i := i + 1;
175	    }
176	}
